CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE IF NOT EXISTS users (id bigserial PRIMARY KEY, telegram_user_id bigint UNIQUE NOT NULL, role text NOT NULL CHECK (role IN ('manager','director','admin')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lead_sources (code text PRIMARY KEY, title text NOT NULL, active boolean NOT NULL DEFAULT true);
INSERT INTO lead_sources(code,title) VALUES ('avito','Авито'),('site','Сайт'),('partners','Партнёры'),('social','Социальные сети'),('yandex','Яндекс'),('other','Другое') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS clients (id bigserial PRIMARY KEY, name text NOT NULL, phone text, telegram_user_id bigint UNIQUE, telegram_username text, security_status text NOT NULL DEFAULT 'unspecified' CHECK (security_status IN ('unspecified','approved','rejected')), status text NOT NULL DEFAULT 'new' CHECK (status IN ('new','active')), club_external_id uuid UNIQUE, club_status text, club_synced_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS client_identifiers (id bigserial PRIMARY KEY, client_id bigint NOT NULL REFERENCES clients(id), kind text NOT NULL, value text NOT NULL, source text, confirmed boolean NOT NULL DEFAULT false, UNIQUE(kind,value));
CREATE TABLE IF NOT EXISTS vehicles (id bigserial PRIMARY KEY, code text UNIQUE NOT NULL, title text NOT NULL, identifier text, available boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS rentals (id bigserial PRIMARY KEY, client_id bigint NOT NULL REFERENCES clients(id), vehicle_id bigint NOT NULL REFERENCES vehicles(id), source text NOT NULL DEFAULT 'other' REFERENCES lead_sources(code), status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','booked','active','completed','cancelled')), starts_at timestamptz NOT NULL, expected_return_at timestamptz NOT NULL, issued_at timestamptz, returned_at timestamptz, amount numeric(14,2) NOT NULL DEFAULT 0, currency char(3) NOT NULL DEFAULT 'RUB', payment_status text NOT NULL DEFAULT 'unpaid' CHECK (payment_status IN ('unpaid','partial','paid','refunded')), damage_comment text, rating integer CHECK (rating BETWEEN 0 AND 5), created_by bigint REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), CHECK (expected_return_at > starts_at));
CREATE INDEX IF NOT EXISTS rentals_vehicle_period_idx ON rentals(vehicle_id, starts_at, expected_return_at) WHERE status IN ('booked','active');
ALTER TABLE rentals ADD CONSTRAINT rentals_no_vehicle_overlap EXCLUDE USING gist (vehicle_id WITH =, tstzrange(starts_at, expected_return_at, '[)') WITH &&) WHERE (status IN ('booked','active'));
CREATE TABLE IF NOT EXISTS payments (id bigserial PRIMARY KEY, rental_id bigint NOT NULL REFERENCES rentals(id), amount numeric(14,2) NOT NULL, kind text NOT NULL, status text NOT NULL, comment text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS deposits (id bigserial PRIMARY KEY, rental_id bigint UNIQUE NOT NULL REFERENCES rentals(id), amount numeric(14,2) NOT NULL DEFAULT 0, return_amount numeric(14,2), due_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'not_paid' CHECK (status IN ('not_paid','held','due','partially_returned','returned','retained')), returned_at timestamptz, returned_by bigint REFERENCES users(id), reason text);
CREATE TABLE IF NOT EXISTS return_inspections (id bigserial PRIMARY KEY, rental_id bigint UNIQUE NOT NULL REFERENCES rentals(id), damaged boolean NOT NULL, comment text, rating integer NOT NULL CHECK (rating BETWEEN 0 AND 5), returned_at timestamptz NOT NULL, employee_id bigint REFERENCES users(id), CHECK (NOT damaged OR length(trim(coalesce(comment,''))) > 0));
CREATE TABLE IF NOT EXISTS club_profiles (client_id bigint PRIMARY KEY REFERENCES clients(id), external_id uuid UNIQUE NOT NULL, status text, synced_at timestamptz NOT NULL, match_confirmed boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS audit_events (id bigserial PRIMARY KEY, actor_telegram_id bigint, entity text NOT NULL, entity_id text NOT NULL, action text NOT NULL, payload jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS scheduled_jobs (id bigserial PRIMARY KEY, kind text NOT NULL, idempotency_key text UNIQUE NOT NULL, scheduled_at timestamptz NOT NULL, attempts integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'pending', last_error text, sent_at timestamptz);
CREATE TABLE IF NOT EXISTS processed_updates (update_id bigint PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS form_states (telegram_id bigint PRIMARY KEY, state jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS client_blacklist (client_id bigint PRIMARY KEY REFERENCES clients(id), added_by_telegram_id bigint NOT NULL, reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS client_attempts (id bigserial PRIMARY KEY, client_id bigint NOT NULL REFERENCES clients(id), attempt_date date NOT NULL DEFAULT current_date, added_by_telegram_id bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(client_id,attempt_date));
ALTER TABLE rentals ADD COLUMN IF NOT EXISTS issued_by_telegram_id bigint;
ALTER TABLE rentals ADD COLUMN IF NOT EXISTS returned_by_telegram_id bigint;
ALTER TABLE return_inspections ADD COLUMN IF NOT EXISTS photo_file_id text;
